            <node TEXT="青年：孩子学习是父母的责任吧？" ID="K1KGZuAxBB" _mubu_text="%3Cspan%3E%E9%9D%92%E5%B9%B4%EF%BC%9A%E5%AD%A9%E5%AD%90%E5%AD%A6%E4%B9%A0%E6%98%AF%E7%88%B6%E6%AF%8D%E7%9A%84%E8%B4%A3%E4%BB%BB%E5%90%A7%EF%BC%9F%3C/span%3E" STYLE="fork"/>
            <node TEXT="哲人：学习所带来的后果——成绩、升学、找不到工作——最终承担者不是父母，而是孩子。因此“学习”是孩子的课题。父母能做的，只有“把马带到水边”——告诉他“这里有水”，但不能按住马头强迫它喝。" ID="AIKEwVQvZS" _mubu_text="%3Cspan%3E%E5%93%B2%E4%BA%BA%EF%BC%9A%E5%AD%A6%E4%B9%A0%E6%89%80%E5%B8%A6%E6%9D%A5%E7%9A%84%E5%90%8E%E6%9E%9C%E2%80%94%E2%80%94%E6%88%90%E7%BB%A9%E3%80%81%E5%8D%87%E5%AD%A6%E3%80%81%E6%89%BE%E4%B8%8D%E5%88%B0%E5%B7%A5%E4%BD%9C%E2%80%94%E2%80%94%E6%9C%80%E7%BB%88%E6%89%BF%E6%8B%85%E8%80%85%E4%B8%8D%E6%98%AF%E7%88%B6%E6%AF%8D%EF%BC%8C%E8%80%8C%E6%98%AF%E5%AD%A9%E5%AD%90%E3%80%82%E5%9B%A0%E6%AD%A4%E2%80%9C%E5%AD%A6%E4%B9%A0%E2%80%9D%E6%98%AF%E5%AD%A9%E5%AD%90%E7%9A%84%E8%AF%BE%E9%A2%98%E3%80%82%E7%88%B6%E6%AF%8D%E8%83%BD%E5%81%9A%E7%9A%84%EF%BC%8C%E5%8F%AA%E6%9C%89%E2%80%9C%E6%8A%8A%E9%A9%AC%E5%B8%A6%E5%88%B0%E6%B0%B4%E8%BE%B9%E2%80%9D%E2%80%94%E2%80%94%E5%91%8A%E8%AF%89%E4%BB%96%E2%80%9C%E8%BF%99%E9%87%8C%E6%9C%89%E6%B0%B4%E2%80%9D%EF%BC%8C%E4%BD%86%E4%B8%8D%E8%83%BD%E6%8C%89%E4%BD%8F%E9%A9%AC%E5%A4%B4%E5%BC%BA%E8%BF%AB%E5%AE%83%E5%96%9D%E3%80%82%3C/span%3E" STYLE="fork"/>
